TITLE = "Practice Test 4: Atmospheres to Small Bodies"
BLURB = "64 questions on planetary atmospheres, weather and climate, the jovian planets and their moons, asteroids, comets and the Kuiper belt."
PRE = {"atmospheres": "atm", "atmhistory": "ah", "jovian": "jov", "moons": "moon", "smallbodies": "sb", "kuiper": "kb"}

def load(p): return json.load(open(p, encoding="utf-8"))
def save(p, d):
    with open(p, "w", encoding="utf-8", newline="\n") as f: json.dump(d, f, indent=1, ensure_ascii=False); f.write("\n")

assert len(Q) == 64 and all(0 <= a < len(o) and len(set(o)) == len(o) for _, _, o, a, _ in Q)
e = load("content/exams-astr207.json")
qs = [{"id": f"x8-{i}", "q": q, "options": o, "answer": a, "why": w} for i, (u, q, o, a, w) in enumerate(Q, 1)]
e["tests"] = [t for t in e["tests"] if t["id"] != "t8"] + [{"id": "t8", "title": TITLE, "blurb": BLURB, "questions": qs}]
save("content/exams-astr207.json", e)
print("t8:", len(qs), "questions")

if "--units" in sys.argv:
    for unit, pre in PRE.items():
        p = f"content/{unit}.json"; d = load(p)
        d["quiz"] = [q for q in d["quiz"] if "-x8-" not in q["id"]]
        for i, (u, q, o, a, w) in enumerate(Q, 1):
            if u == unit:
                d["quiz"].append({"id": f"{pre}-x8-{i}", "q": q, "options": o, "answer": a, "why": w, "source": f"Owner's Practice Test 4 (Q{i})"})
        save(p, d)
        print(unit, "quiz", len(d["quiz"]))
